import sys
def patch_file(path, edits, label):
    data=open(path,'rb').read().decode('utf-8')
    for old,new,guard in edits:
        if guard and guard in data:
            print('['+label+'] skip '+guard[:16], file=sys.stderr); continue
        c=data.count(old)
        if c!=1:
            print('['+label+'] ANCHOR x'+str(c)+' :: '+old[:40], file=sys.stderr); sys.exit(1)
        data=data.replace(old,new,1)
    open(path,'wb').write(data.encode('utf-8'))
    print('['+label+'] ok', file=sys.stderr)
